package com.example.editor.project;

import java.nio.file.Path;
import org.springframework.boot.context.properties.ConfigurationProperties;

/** Configuración del módulo completo de proyectos locales. */
@ConfigurationProperties(prefix = "dsl.projects.local")
public class LocalProjectProperties {
    private boolean enabled = true;
    private Path registryDirectory = Path.of("./data/projects");
    private long maxEditableFileSizeBytes = 5L * 1024L * 1024L;
    private long maxUploadFileSizeBytes = 25L * 1024L * 1024L;
    private long maxArchiveSizeBytes = 250L * 1024L * 1024L;
    private int maxTreeDepth = 48;
    private int maxTreeEntries = 20_000;
    private boolean changeDetectionEnabled = true;
    private boolean allowSymbolicLinks = false;
    private int recentProjectLimit = 20;
    private int maxArchiveEntries = 10000;
    private int maxNestedArchiveDepth = 4;
    private double maxArchiveCompressionRatio = 150.0;
    private long maxArchiveReadMillis = 30_000L;
    private int maxSearchResults = 200;
    private boolean nativePathPickerEnabled = true;
    private boolean nativePathPickerLocalOnly = true;
    /** Descripción: Evalúa la condición «isEnabled» sin modificar el estado externo. Entradas: no requiere parámetros de entrada. Salida: devuelve un indicador que expresa el resultado de la condición. */ public boolean isEnabled() { return enabled; }
    /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setEnabled». Entradas: enabled: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setEnabled(boolean enabled) { this.enabled = enabled; }
    /** Descripción: Obtiene la información correspondiente a «getRegistryDirectory» dentro de LocalProjectProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public Path getRegistryDirectory() { return registryDirectory; }
    /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setRegistryDirectory». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setRegistryDirectory(Path value) { registryDirectory = value; }
    /** Descripción: Obtiene la información correspondiente a «getMaxEditableFileSizeBytes» dentro de LocalProjectProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getMaxEditableFileSizeBytes() { return maxEditableFileSizeBytes; }
    /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setMaxEditableFileSizeBytes». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaxEditableFileSizeBytes(long value) { maxEditableFileSizeBytes = value; }
    /** Descripción: Obtiene la información correspondiente a «getMaxUploadFileSizeBytes» dentro de LocalProjectProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getMaxUploadFileSizeBytes() { return maxUploadFileSizeBytes; }
    /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setMaxUploadFileSizeBytes». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaxUploadFileSizeBytes(long value) { maxUploadFileSizeBytes = value; }
    /** Descripción: Obtiene la información correspondiente a «getMaxArchiveSizeBytes» dentro de LocalProjectProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getMaxArchiveSizeBytes() { return maxArchiveSizeBytes; }
    /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setMaxArchiveSizeBytes». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaxArchiveSizeBytes(long value) { maxArchiveSizeBytes = value; }
    /** Descripción: Obtiene la información correspondiente a «getMaxTreeDepth» dentro de LocalProjectProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaxTreeDepth() { return maxTreeDepth; }
    /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setMaxTreeDepth». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaxTreeDepth(int value) { maxTreeDepth = value; }
    /** Descripción: Obtiene el máximo configurable de entradas que puede recorrer una visualización o regeneración del árbol de proyecto. Entradas: no requiere parámetros. Salida: devuelve el presupuesto de cardinalidad del árbol. */ public int getMaxTreeEntries() { return maxTreeEntries; }
    /** Descripción: Configura el máximo de entradas del árbol evitando valores nulos o destructivos. Entradas: value: nuevo límite. Salida: actualiza el presupuesto con un mínimo de una entrada. */ public void setMaxTreeEntries(int value) { maxTreeEntries = Math.max(1, value); }
    /** Descripción: Evalúa la condición «isChangeDetectionEnabled» sin modificar el estado externo. Entradas: no requiere parámetros de entrada. Salida: devuelve un indicador que expresa el resultado de la condición. */ public boolean isChangeDetectionEnabled() { return changeDetectionEnabled; }
    /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setChangeDetectionEnabled». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setChangeDetectionEnabled(boolean value) { changeDetectionEnabled = value; }
    /** Descripción: Evalúa la condición «isAllowSymbolicLinks» sin modificar el estado externo. Entradas: no requiere parámetros de entrada. Salida: devuelve un indicador que expresa el resultado de la condición. */ public boolean isAllowSymbolicLinks() { return allowSymbolicLinks; }
    /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setAllowSymbolicLinks». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setAllowSymbolicLinks(boolean value) { allowSymbolicLinks = value; }
    /** Descripción: Obtiene la información correspondiente a «getRecentProjectLimit» dentro de LocalProjectProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getRecentProjectLimit() { return recentProjectLimit; }
    /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setRecentProjectLimit». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setRecentProjectLimit(int value) { recentProjectLimit = value; }
    /** Descripción: Obtiene la información correspondiente a «getMaxArchiveEntries» dentro de LocalProjectProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaxArchiveEntries() { return maxArchiveEntries; }
    /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setMaxArchiveEntries». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaxArchiveEntries(int value) { maxArchiveEntries = value; }
    /** Profundidad máxima de contenedores ZIP/JAR/WAR/EAR anidados durante el análisis externo. */ /** Descripción: Obtiene la información correspondiente a «getMaxNestedArchiveDepth» dentro de LocalProjectProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaxNestedArchiveDepth() { return maxNestedArchiveDepth; }
    /** Configura la profundidad máxima de contenedores anidados. */ /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setMaxNestedArchiveDepth». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaxNestedArchiveDepth(int value) { maxNestedArchiveDepth = Math.max(0, value); }
    /** Ratio máximo de expansión aceptado durante el análisis de archivos externos. */ /** Descripción: Obtiene la información correspondiente a «getMaxArchiveCompressionRatio» dentro de LocalProjectProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public double getMaxArchiveCompressionRatio() { return maxArchiveCompressionRatio; }
    /** Configura el ratio máximo de expansión aceptado. */ /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setMaxArchiveCompressionRatio». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaxArchiveCompressionRatio(double value) { maxArchiveCompressionRatio = Math.max(1D, value); }
    /** Tiempo máximo de lectura de un archivo externo en milisegundos. */ /** Descripción: Obtiene la información correspondiente a «getMaxArchiveReadMillis» dentro de LocalProjectProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getMaxArchiveReadMillis() { return maxArchiveReadMillis; }
    /** Configura el tiempo máximo de lectura de archivos externos. */ /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setMaxArchiveReadMillis». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaxArchiveReadMillis(long value) { maxArchiveReadMillis = Math.max(1000L, value); }
    /** Descripción: Obtiene la información correspondiente a «getMaxSearchResults» dentro de LocalProjectProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaxSearchResults() { return maxSearchResults; }
    /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setMaxSearchResults». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaxSearchResults(int value) { maxSearchResults = value; }
    /** Descripción: Evalúa la condición «isNativePathPickerEnabled» sin modificar el estado externo. Entradas: no requiere parámetros de entrada. Salida: devuelve un indicador que expresa el resultado de la condición. */ public boolean isNativePathPickerEnabled() { return nativePathPickerEnabled; }
    /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setNativePathPickerEnabled». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setNativePathPickerEnabled(boolean value) { nativePathPickerEnabled = value; }
    /** Descripción: Evalúa la condición «isNativePathPickerLocalOnly» sin modificar el estado externo. Entradas: no requiere parámetros de entrada. Salida: devuelve un indicador que expresa el resultado de la condición. */ public boolean isNativePathPickerLocalOnly() { return nativePathPickerLocalOnly; }
    /** Descripción: Actualiza el estado gestionado por LocalProjectProperties mediante la operación «setNativePathPickerLocalOnly». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setNativePathPickerLocalOnly(boolean value) { nativePathPickerLocalOnly = value; }
}
